import{_ as a,f as n,o as e,aq as o}from"./chunks/framework.BvNt3gUw.js";const y=JSON.parse('{"title":"配置信息","description":"","frontmatter":{},"headers":[],"relativePath":"zh_CN/getting-started/configuration.md","filePath":"zh_CN/getting-started/configuration.md","lastUpdated":1789894384000}'),l={name:"zh_CN/getting-started/configuration.md"};function p(r,s,c,t,d,i){return e(),n("div",null,s[0]||(s[0]=[o(`<h1 id="配置信息" tabindex="-1">配置信息 <a class="header-anchor" href="#配置信息" aria-label="Permalink to “配置信息”">​</a></h1><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to “简介”">​</a></h2><p>Goravel 框架所有配置文件都保存在 <code>config</code> 目录中。 你可以进入具体文件查看配置说明，根据项目需要灵活配置。</p><h2 id="环境配置" tabindex="-1">环境配置 <a class="header-anchor" href="#环境配置" aria-label="Permalink to “环境配置”">​</a></h2><p>在不同的环境运行应用程序，通常需要不同的配置。 例如，你可能希望在本地打开 Debug 模式，但生产环境不需要。</p><p>因此，框架在根目录提供了 <code>.env.example</code> 文件。 需要你在开发前，复制该文件并重命名为 <code>.env</code>，根据项目需要修改 <code>.env</code> 文件中的配置项。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>.env</code> 文件不应该加入版本控制，因为多人协作时，不同的开发人员有可能使用不同的配置，不同的部署环境配置也不相同。</p></div><p>此外，如果有入侵者获得了你的代码仓库访问权限，将会有暴露敏感配置的风险。 如果你想新增新的配置项，可以添加到 <code>.env.example</code> 文件中，以此来同步所有开发者的配置。</p><h3 id="注册配置" tabindex="-1">注册配置 <a class="header-anchor" href="#注册配置" aria-label="Permalink to “注册配置”">​</a></h3><p>所有配置文件都将通过 <code>bootstrap/app.go</code> 文件中的 <code>WithConfig</code> 函数进行注册。 由于它是配置文件中的 <code>init</code> 函数，因此你无需逐一注册每个配置文件。 只需按如下方式调用 <code>WithConfig</code> 函数：</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">func </span><span style="color:#0077B3;">Boot</span><span style="color:#68747D;">()</span><span style="color:#101820;"> contractsfoundation</span><span style="color:#68747D;">.</span><span style="color:#101820;">Application </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">	return foundation</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Setup</span><span style="color:#68747D;">().</span></span>
<span class="line"><span style="color:#0077B3;">		WithConfig</span><span style="color:#68747D;">(</span><span style="color:#101820;">config</span><span style="color:#68747D;">.</span><span style="color:#101820;">Boot</span><span style="color:#68747D;">).</span></span>
<span class="line"><span style="color:#0077B3;">		Create</span><span style="color:#68747D;">()</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="获取环境配置" tabindex="-1">获取环境配置 <a class="header-anchor" href="#获取环境配置" aria-label="Permalink to “获取环境配置”">​</a></h2><p>使用如下方法，可获取 <code>.env</code> 文件中的配置项：</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#68747D;">// 第一个参数为配置键，第二个参数为默认值</span></span>
<span class="line"><span style="color:#101820;">facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Config</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;APP_NAME&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;goravel&quot;</span><span style="color:#68747D;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="获取配置值" tabindex="-1">获取配置值 <a class="header-anchor" href="#获取配置值" aria-label="Permalink to “获取配置值”">​</a></h2><p>你可以轻松的在应用程序的任何位置使用全局 <code>facades.Config()</code> 函数来访问 <code>config</code> 目录中的配置值。 配置值的访问可以使用「点」语法。 还可以指定默认值，如果配置选项不存在，则返回默认值：</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#68747D;">// 通过断言获取配置</span></span>
<span class="line"><span style="color:#101820;">facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Config</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Get</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;app.name&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;goravel&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">// 获取字符串类型的配置</span></span>
<span class="line"><span style="color:#101820;">facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Config</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">GetString</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;app.name&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;goravel&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">// 获取整形类型的配置</span></span>
<span class="line"><span style="color:#101820;">facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Config</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">GetInt</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;app.int&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> 1)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">// 获取布尔类型的配置</span></span>
<span class="line"><span style="color:#101820;">facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Config</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">GetBool</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;app.debug&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> true</span><span style="color:#68747D;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h2 id="设置配置值" tabindex="-1">设置配置值 <a class="header-anchor" href="#设置配置值" aria-label="Permalink to “设置配置值”">​</a></h2><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Config</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Add</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;path&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;value1&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#101820;">facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Config</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Add</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;path.with.dot.case1&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;value1&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#101820;">facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Config</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Add</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;path.with.dot&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">any</span><span style="color:#68747D;">{</span><span style="color:#68747D;">&quot;case3&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;"> &quot;value3&quot;</span><span style="color:#68747D;">})</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="获取项目信息" tabindex="-1">获取项目信息 <a class="header-anchor" href="#获取项目信息" aria-label="Permalink to “获取项目信息”">​</a></h2><p>可以使用 <code>artisan about</code> 命令来查看框架的版本、配置等信息。</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#0077B3;">./artisan</span><span style="color:#101820;"> about</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="维护模式" tabindex="-1">维护模式 <a class="header-anchor" href="#维护模式" aria-label="Permalink to “维护模式”">​</a></h3><p>如果你安装了 Route facade，可以使用 <code>down</code> 命令将应用程序置于维护模式。默认情况下，Goravel 使用 <code>file</code> 维护驱动，并将维护元数据存储在 <code>framework/maintenance.json</code> 存储路径中：</p><div class="language-shell line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#0077B3;">./artisan</span><span style="color:#101820;"> down</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>你可以为维护响应提供自定义原因和 HTTP 状态码：</p><div class="language-shell line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#0077B3;">./artisan</span><span style="color:#101820;"> down</span><span style="color:#101820;"> --reason=</span><span style="color:#68747D;">&quot;正在升级数据库&quot;</span><span style="color:#101820;"> --status=503</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>down</code> 命令还支持在维护模式下将用户重定向到某个路径或渲染一个视图：</p><div class="language-shell line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#0077B3;">./artisan</span><span style="color:#101820;"> down</span><span style="color:#101820;"> --redirect=/maintenance</span></span>
<span class="line"><span style="color:#0077B3;">./artisan</span><span style="color:#101820;"> down</span><span style="color:#101820;"> --render=errors/503</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>使用 <code>--render</code> 时，视图必须已经存在。如果提供了 <code>--redirect</code> 或 <code>--render</code>，则不会使用 <code>--reason</code> 的响应正文。</p><p>你可以通过设置密钥来允许临时访问应用程序。用户可以通过在访问应用程序时携带匹配的 <code>secret</code> 查询参数来绕过维护模式：</p><div class="language-shell line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#0077B3;">./artisan</span><span style="color:#101820;"> down</span><span style="color:#101820;"> --secret=let-me-in</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span>https://example.com?secret=let-me-in</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>你还可以让 Goravel 为你生成一个随机密钥：</p><div class="language-shell line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#0077B3;">./artisan</span><span style="color:#101820;"> down</span><span style="color:#101820;"> --with-secret</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>维护驱动和缓存存储可以在 <code>config/app.go</code> 中配置。默认配置读取 <code>APP_MAINTENANCE_DRIVER</code> 和 <code>APP_MAINTENANCE_STORE</code> 环境变量：</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#68747D;">&quot;maintenance&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">any</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    &quot;driver&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;APP_MAINTENANCE_DRIVER&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;file&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">    &quot;store&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;">  config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;APP_MAINTENANCE_STORE&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">},</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>如果你的应用程序在多个服务器上运行，你可以使用 <code>cache</code> 维护驱动，使所有服务器共享相同的维护状态。在 <code>.env</code> 文件中配置驱动以及可选的缓存存储名称：</p><div class="language-ini line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">APP_MAINTENANCE_DRIVER</span><span style="color:#68747D;">=</span><span style="color:#101820;">cache</span></span>
<span class="line"><span style="color:#101820;">APP_MAINTENANCE_STORE</span><span style="color:#68747D;">=</span><span style="color:#101820;">redis</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>如果未设置 <code>APP_MAINTENANCE_STORE</code>，Goravel 将使用默认缓存存储。在其中一台服务器上运行 <code>down</code> 或 <code>up</code> 命令会更新所有使用相同缓存存储的服务器的维护状态。</p><p>要将应用程序退出维护模式，请运行 <code>up</code> 命令：</p><div class="language-shell line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#0077B3;">./artisan</span><span style="color:#101820;"> up</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="禁用-runners" tabindex="-1">禁用 Runners <a class="header-anchor" href="#禁用-runners" aria-label="Permalink to “禁用 Runners”">​</a></h3><p>当应用程序通过 <code>app.Start()</code> 启动时，Goravel 会自动运行由服务提供者注册的自动运行 <a href="./../architecture-concepts/service-providers.html#runners">runners</a>，例如 HTTP 服务器、gRPC 服务器、队列工作器、调度器和遥测。你可以通过设置 <code>config/app.go</code> 中的 <code>app.disabled_runners</code> 选项，在主进程中选择性地跳过特定的 runner。框架会集中评估此列表，因此相同的选项适用于任何当前或未来的 runner。</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">config/app.go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#68747D;">&quot;app&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">any</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    &quot;env&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;">   config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;APP_ENV&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;production&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">    &quot;debug&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> config</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Env</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;APP_DEBUG&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> false</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">    &quot;disabled_runners&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;"> []</span><span style="color:#101820;">string</span><span style="color:#68747D;">{</span><span style="color:#68747D;">&quot;goravel:schedule&quot;</span><span style="color:#68747D;">},</span></span>
<span class="line"><span style="color:#68747D;">},</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>该值是一个 glob 模式切片，与每个 runner 的签名进行匹配。框架使用 Go 的 <a href="https://pkg.go.dev/path#Match" target="_blank" rel="noreferrer"><code>path.Match</code></a> 进行匹配，因此 <code>*</code> 是唯一支持的通配符。框架 runner 的签名如下：</p><table tabindex="0"><thead><tr><th>签名</th><th>Runner</th><th>启动者</th></tr></thead><tbody><tr><td><code>goravel:http</code></td><td><code>HTTPRunner</code>（HTTP 服务器）</td><td><code>http</code> 服务提供者</td></tr><tr><td><code>goravel:grpc</code></td><td><code>GrpcRunner</code>（gRPC 服务器）</td><td><code>grpc</code> 服务提供者</td></tr><tr><td><code>goravel:queue</code></td><td><code>QueueRunner</code>（队列工作器）</td><td><code>queue</code> 服务提供者</td></tr><tr><td><code>goravel:schedule</code></td><td><code>ScheduleRunner</code>（调度器）</td><td><code>schedule</code> 服务提供者</td></tr><tr><td><code>goravel:telemetry</code></td><td><code>TelemetryRunner</code></td><td><code>telemetry</code> 服务提供者</td></tr></tbody></table><p>常见模式：</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#68747D;">// Web 容器 — 仅跳过调度器，使其在专用容器上运行</span></span>
<span class="line"><span style="color:#68747D;">&quot;disabled_runners&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;"> []</span><span style="color:#101820;">string</span><span style="color:#68747D;">{</span><span style="color:#68747D;">&quot;goravel:schedule&quot;</span><span style="color:#68747D;">},</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">// 仅调度器容器 — 禁用 http、queue、grpc</span></span>
<span class="line"><span style="color:#68747D;">&quot;disabled_runners&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;"> []</span><span style="color:#101820;">string</span><span style="color:#68747D;">{</span><span style="color:#68747D;">&quot;goravel:http&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;goravel:queue&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;goravel:grpc&quot;</span><span style="color:#68747D;">},</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">// 禁用所有框架 runner</span></span>
<span class="line"><span style="color:#68747D;">&quot;disabled_runners&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;"> []</span><span style="color:#101820;">string</span><span style="color:#68747D;">{</span><span style="color:#68747D;">&quot;goravel:*&quot;</span><span style="color:#68747D;">},</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">// 紧急开关：在主进程中不运行任何自动运行的 runner</span></span>
<span class="line"><span style="color:#68747D;">&quot;disabled_runners&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;"> []</span><span style="color:#101820;">string</span><span style="color:#68747D;">{</span><span style="color:#68747D;">&quot;*&quot;</span><span style="color:#68747D;">},</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>模式按顺序评估，第一个匹配生效。无效的模式（例如未匹配的括号）会被记录为警告，runner 保持运行，因此配置中的拼写错误永远不会导致启动崩溃。</p><p>你通过 <code>WithRunners</code> 注册的用户自定义 runner 不受 <code>goravel:*</code> 命名空间的影响。使用 runner 自身的签名来禁用它。</p>`,51)]))}const b=a(l,[["render",p]]);export{y as __pageData,b as default};
